"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[431],{1310(e){e.exports=JSON.parse('{"title":"Parse, Don\u2019t Validate in TypeScript","date":"2026-04-22","coverUrl":"/kudzu-based-bench/assets/notion/bfb167651b969bc8.png","html":"<h1 data-notion-block-id=\\"343e548d-8a8e-80b6-9f01-f1ec0043ca6a\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"343e548d-8a8e-80ac-8776-dc20ae6d4c57\\" id=\\"343e548d-8a8e-80ac-8776-dc20ae6d4c57\\">Parse, Don\u2019t Validate in TypeScript</h2><a href=\\"https://cekrem.github.io/posts/parse-dont-validate-typescript/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://cekrem.github.io/posts/parse-dont-validate-typescript/</a><p data-notion-block-id=\\"347e548d-8a8e-8028-a05e-de3640c64861\\">Parse, Don\u2019t Validate \uc6d0\uce59(\uac04\ub2e8\ud558\uac8c \ub9d0\ud558\uc790\uba74, \ud0c0\uc785 \uc2dc\uc2a4\ud15c\uc774 \uc774\uc720\ub97c \uac00\uc9c0\uace0 \uc788\ub3c4\ub85d \uc124\uacc4)\uc5d0 \uae30\ubc18\ud574\uc11c <a href=\\"https://colinhacks.com/essays/zod\\">zod\uac00 \ub9cc\ub4e4\uc5b4</a>\uc84c\uc9c0\ub9cc, zod\uac19\uc740 \uc720\ud6a8\uc131 \uac80\uc0ac \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc801\uc6a9\ud558\ub294 \uac83\uc774 TypeScript\uc5d0\uc11c \uc6d0\uce59\uc744 \uc644\ubcbd\ud558\uac8c \uc9c0\ud0a4\uae30\ub294 \uc5b4\ub824\uc6b0\uba70, \uc5b4\ub5a4 \uc0dd\uac01\uc73c\ub85c \uc124\uacc4\ud574\uc57c \uc77c\uad00\ub41c \uacbd\uacc4\ub97c \uac16\ub294 \ucf54\ub4dc\ub97c \ub9cc\ub4e4 \uc218 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"343e548d-8a8e-806f-80d2-ecdbac579388\\" id=\\"343e548d-8a8e-806f-80d2-ecdbac579388\\">Tanstack\uc758 RSC \uc811\uadfc\ubc95</h2><a href=\\"https://tanstack.com/blog/react-server-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/blog/react-server-components</a><p data-notion-block-id=\\"343e548d-8a8e-80d3-908d-c3714a089cc1\\"><code>\\"use server\\"</code>\uc640 <code>\\"use client\\"</code>\ub85c\ub9cc RSC \uad6c\ubd84\uc744 \uc9d3\uace0 \ub8e8\ud2b8 \ucef4\ud3ec\ub10c\ud2b8\ub97c \uae30\ubcf8\uc73c\ub85c Server Component\ub85c \ub9cc\ub4e4\uace0 <code>\\"use cache\\"</code>\uc640 cache component\ub85c \uce90\uc2f1\uc744 \ub2f4\ub2f9\ud558\ub294 Next.js\uc758 \uc811\uadfc\ubc95\uacfc \ub2e4\ub974\uac8c \uce90\uc2f1 \ub808\uc774\uc5b4\ub97c \ub098\ub204\uace0 RSC\ub97c React Router\ub098 Next.js Page Router\ub97c \uc774\uc6a9\ud55c\ub2e4\uba74 \uc775\uc219\ud55c \uba58\ud0c8 \ubaa8\ub378\uc5d0 \uc790\uc2e0\uc758 \uc0c1\ud669\uc5d0 \ub9de\uac8c \uc801\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uc5ec\ub7ec \uae30\ub2a5\uc744 \uc81c\uacf5\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c RSC\ub97c \uc81c\uacf5\ud558\ub294 \uc811\uadfc\ubc95\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Tanstack Router\uc5d0\uc11c\uc758 RSC \uc811\uadfc\ubc95\uc774 \uc544\uc9c1 \uc2e4\ud5d8 \ub2e8\uacc4\uc774\uc9c0\ub9cc, Next.js\uc758 \ubc29\uc2dd\uc774 \uac1c\ubc1c\uc790\ub4e4 \uc0ac\uc774\uc5d0\uc11c \ub9ce\uc740 \ube44\ud310\uacfc \uc624\ub958\uc5d0 \ubd80\ub52b\ud614\ub4ef\uc774, \uc0c8\ub85c\uc6b4 RSC \uc811\uadfc\ubc95\uc744 \uc9c0\ucf1c\ubcfc\ub9cc\ud560 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c <a href=\\"https://ones-to-watch.ethansup.net/news/post/301e548d-8a8e-8053-a33f-e9bcc696088d#301e548d-8a8e-802c-af4d-e98da8bff680\\">Next.js\uc5d0\uc11c Tanstack Start\ub85c\uc758 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uae00</a>\ub3c4 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"347e548d-8a8e-806c-9113-cd7da44736c0\\" id=\\"347e548d-8a8e-806c-9113-cd7da44736c0\\">\uc88b\uc740 \uc544\ud0a4\ud14d\uccd0\ub780?</h2><a href=\\"https://tkdodo.eu/blog/the-vertical-codebase\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/the-vertical-codebase</a><p data-notion-block-id=\\"347e548d-8a8e-80f0-a420-ea68eff74920\\">\ucf54\ub4dc\uc5d0 \ub300\ud574 \uc218\uc9c1 \uad6c\uc870\ub97c \uc5b4\ub5bb\uac8c \uc124\uacc4\ud560\uc9c0\uc5d0 \ub300\ud574 \uace0\ubbfc\uac70\ub9ac\ub4e4\uc744 \uac04\ub2e8\ud558\uac8c \ud6d1\uc5b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \ubb3c\ub860 \uc62c\ubc14\ub978 \uc544\ud0a4\ud14d\uccd0\ub294 \ud56d\uc0c1 \ud300\uc5d0 \ub9de\uac8c, \ube44\uc988\ub2c8\uc2a4\uc5d0 \ub9de\uac8c \ud300\uc5d0\uc11c \uc18c\ud1b5\ud574\uac00\uba74\uc11c \ub9cc\ub4e4\uc5b4\uac00\uc57c \ud558\ubbc0\ub85c \uc218\uc9c1 \uad6c\uc870\ub97c \uc124\uacc4\ud558\ub294 \ubc29\uc2dd\uc740 \ud56d\uc0c1 \uc0c1\ud669\uc5d0 \ub9de\uac8c \ub9cc\ub4e4\uc5b4\uc57c \ud569\ub2c8\ub2e4. Atomic Design\uacfc Feature Sliced Design\uc740 \uc88b\uc740 \uc608\uc2dc\uac00 \ub420 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \uc740\ud0c4\ud658\uc774 \ub420 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"343e548d-8a8e-80f6-9f42-f002c7fa3748\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"347e548d-8a8e-80f0-afc6-eac1a51aea0e\\" id=\\"347e548d-8a8e-80f0-afc6-eac1a51aea0e\\">Web Animation with Disney \uc560\ub2c8\uba54\uc774\uc158 \uc6d0\uce59</h2><a href=\\"https://www.joshwcomeau.com/animation/squash-and-stretch/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/animation/squash-and-stretch/</a><p data-notion-block-id=\\"347e548d-8a8e-80ae-a721-eebc5cba19f0\\">\uac04\ub2e8\ud55c Interaction\uc5d0\uc11c \uc801\uc6a9\ud560 \ub9cc\ud55c Disney \uc6d0\uce59\uc778 squash and stretch\ub97c \uc6f9 \uc560\ub2c8\uba54\uc774\uc158\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc801\uc6a9\ud558\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"344e548d-8a8e-808c-99a2-e8de171574a4\\" id=\\"344e548d-8a8e-808c-99a2-e8de171574a4\\">SVG \ud544\ud130 \uae30\ubcf8 \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://frontendmasters.com/blog/svg-filters-guide-getting-started-with-the-basics/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/svg-filters-guide-getting-started-with-the-basics/</a><h2 data-notion-block-id=\\"344e548d-8a8e-80fc-8161-d38652ecba78\\" id=\\"344e548d-8a8e-80fc-8161-d38652ecba78\\">React Native \ube4c\ub4dc \ucd5c\uc801\ud654</h2><a href=\\"https://themythicalengineer.com/the-complete-guide-to-react-native-build-optimization.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://themythicalengineer.com/the-complete-guide-to-react-native-build-optimization.html</a><h1 data-notion-block-id=\\"343e548d-8a8e-808e-b92e-d994c7e3f193\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://developers.google.com/search/blog/2026/04/back-button-hijacking\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developers.google.com/search/blog/2026/04/back-button-hijacking</a><p data-notion-block-id=\\"347e548d-8a8e-80de-b53d-d01df21f9bf4\\">\uad6c\uae00\uc758 \uc0c8\ub85c\uc6b4 \uc2a4\ud338 \uc815\ucc45\uc73c\ub85c \\"\ub4a4\ub85c \ubc84\ud2bc \ud558\uc774\uc7ac\ud0b9\\"\uc744 \uac80\uc0ac\ud55c\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://valentinprugnaud.dev/posts/2026/04/if-you-cant-see-the-boundary-you-cant-reason-about-the-system\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://valentinprugnaud.dev/posts/2026/04/if-you-cant-see-the-boundary-you-cant-reason-about-the-system</a><p data-notion-block-id=\\"344e548d-8a8e-80fe-9fac-c3f0713b089c\\">RSC\uc758 \uacbd\uacc4\ub97c UI\uc0c1\uc73c\ub85c \ubcfc \uc218 \uc788\ub3c4\ub85d \ub3c4\uc640\uc8fc\ub294 RSC boundary\uc5d0 \ub300\ud55c \uc18c\uac1c\uc785\ub2c8\ub2e4.</p>"}')}}]);